import{z as d,x as p,o as e,c as m,q as t,j as n,D as s,d as i,s as o,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Kruskal 与 Prim","description":"","frontmatter":{"title":"Kruskal 与 Prim","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mst-kruskal-prim.md","filePath":"cs/mst-kruskal-prim.md","lastUpdated":1791063341000}'),u={name:"cs/mst-kruskal-prim.md"};function B(k,a,A,h,P,c){const l=p("Mermaid");return e(),m("div",null,[a[2]||(a[2]=t('<h1 id="kruskal-与-prim" tabindex="-1">Kruskal 与 Prim <a class="header-anchor" href="#kruskal-与-prim" aria-label="Permalink to &quot;Kruskal 与 Prim&quot;">​</a></h1><div class="epigraph"><p>连通无向图上，边权之和最小的生成树可以由安全边逐步长成：要么在森林间加最轻边，要么从一棵树向外长。</p><footer>—— 据 Kruskal, On the Shortest Spanning Subtree, 1956；Prim, Shortest Connection Networks, 1957；CLRS 第 23 章整理</footer></div><p>上一课<a href="/cs/johnson-apsp">Johnson 全源</a>给了点对距离。最小生成树问的是另一件事：用 \\(|V|-1\\) 条边连通、总权最小。本课不重做全源。缺口是：<strong>安全边</strong>——加进去不破坏某棵 MST 的前缀。<a href="/cs/union-find">并查集</a>与堆已在。本课交出 Kruskal 与 Prim。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向连通、边权可比较（可负；负环不是 MST 的语言）。切分定理：对任意切分，横跨切分的最轻边是某 MST 的安全边。Kruskal：边按权排序，若两端不在同一连通块则加入（并查集）。Prim：从一棵树出发，反复加树到外部的最轻边（优先队列）。</p><p><span class="marginnote">直觉类比：切分定理像把全班分成两组，横跨两组的「关系」里最便宜的那条总是保险的——两组迟早要连通，弃掉最便宜的横跨边、改用更贵的，总权只会更大。</span></p><p>与 Dijkstra 酷似但目标不同：Prim 的键是「到树的边权」，不是「到源的路权」。不要把 MST 当最短路树。</p><p><span class="marginnote">常见误区：初学者容易以为树上任意两点间的路径就是最短路，实际上可能要绕远——MST 最小化的是全树 \\(|V|-1\\) 条边的权之和，并不保证任何一对点的点对距离最短，那是 Dijkstra/Johnson 的任务。</span></p><h3 id="两种贪心同一套切分" tabindex="-1">两种贪心同一套切分 <a class="header-anchor" href="#两种贪心同一套切分" aria-label="Permalink to &quot;两种贪心同一套切分&quot;">​</a></h3><p>Kruskal 的切分是当前森林的块；Prim 的切分是树内/树外。切分定理共用。正确性走贪心的安全边，一般贪心模板在<a href="/cs/greedy-correct">后课</a>，本课先把 MST 做成实例。</p><p><span class="marginnote">Kruskal 1956、Prim 1957（Borůvka 1926 更早，本课点名第三算法但不实现）。并查集加路径压缩与按秩，Kruskal 几乎是 \\(O(E\\log V)\\) 排序主导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kruskal：排序 \\(E\\)，对每条边 <code>Find</code> 两端，不同则 <code>Union</code> 并收录。Prim：类似 Dijkstra 的循环，松弛的是树外顶点到树的最小边权。</p>',13)),(e(),n(E,null,{default:s(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%BF%9E%E9%80%9A%E6%97%A0%E5%90%91%E5%9B%BE%22%5D%20--%3E%20K%5B%22Kruskal%EF%BC%9A%E6%8E%92%E5%BA%8F%20%2B%20%E5%B9%B6%E6%9F%A5%E9%9B%86%22%5D%0A%20%20G%20--%3E%20P%5B%22Prim%EF%BC%9A%E6%A0%91%E5%90%91%E5%A4%96%20%2B%20%E5%A0%86%22%5D%0A%20%20K%20--%3E%20MST%5B%22%E6%9C%80%E5%B0%8F%E7%94%9F%E6%88%90%E6%A0%91%22%5D%0A%20%20P%20--%3E%20MST%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不连通则生成森林。本课默认连通。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"稀疏图 Kruskal 常更干净（排序一次）。稠密 Prim 用邻接矩阵扫描可 \\(O(V^2)\\)。唯一性：边权互异则 MST 唯一；否则可以多棵，算法给出其中一棵。最大生成树把权取负即可，仍是本课。",-1)),a[6]||(a[6]=r("p",null,"与最短路：负权对 MST 无妨（无向且不走环累加定义）。Dijkstra 仍要非负。",-1)),(e(),n(E,null,{default:s(()=>[o(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SORT%5B%22%E8%BE%B9%E6%8C%89%E6%9D%83%E4%BB%8E%E5%B0%8F%E5%88%B0%E5%A4%A7%22%5D%20--%3E%20LOOK%5B%22%E5%8F%96%E4%B8%8B%E4%B8%80%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20LOOK%20--%3E%20Q%7B%22%E4%B8%A4%E7%AB%AF%E5%9C%A8%E5%90%8C%E4%B8%80%E8%BF%9E%E9%80%9A%E5%9D%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20TAKE%5B%22Union%20%E5%B9%B6%E6%94%B6%E5%BD%95%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20SKIP%5B%22%E4%B8%A2%E5%BC%83%3A%20%E4%BC%9A%E6%88%90%E7%8E%AF%22%5D%0A%20%20TAKE%20--%3E%20LOOK%0A%20%20TAKE%20--%3E%20DONE%5B%22%E6%94%B6%E6%BB%A1%20V-1%20%E6%9D%A1%2C%20%E5%81%9C%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">数字实例：4 个顶点 6 条边的图，Kruskal 排序后逐条扫描，一旦收满 \\(|V|-1=3\\) 条边即可停机——剩下的边根本不用看，这正是它比「枚举所有生成树」省事的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理有向图的最小树形图（Edmonds/Chu–Liu）。不写度约束、Steiner 树——那些或 NP 或另一模型。后课最大流换成容量与割，不是生成树。</p><p>后课默认：MST = Kruskal 或 Prim；切分定理保证贪心安全。流网络是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切分上的最轻边安全；Kruskal 并查集，Prim 长树。</li><li>稀疏常 Kruskal \\(O(E\\log V)\\)；稠密 Prim \\(O(V^2)\\)。</li><li>MST 不是最短路树；负权可接受。</li><li>出处：Kruskal, 1956；Prim, 1957；CLRS 第 23 章。</li></ul>',6))])}const K=d(u,[["render",B]]);export{S as __pageData,K as default};
